# =============================================================================
# Cuts read from the optimal simplex tableau of the LP relaxation:
# the standard intersection cut (SIC) and the Gomory mixed-integer (GMI) cut.
#
# Both work in the space of the non-basic variables (structural and slack) of
# the normal form  [A I][x; s] = b. For a basic integer variable x_k with a
# fractional value, its tableau row is
#
#     x_k + Σ_{j ∈ N} ā_j x_j = b̄,        f0 = b̄ - ⌊b̄⌋ ∈ (0, 1).
#
# The LP cone at the vertex x̄ is generated by one ray per non-basic variable
# x_j; along ray j, x_k moves by -ā_j per unit step.
#
# * SIC (Balas 1971): walk along each ray until x_k reaches ⌊b̄⌋ or ⌈b̄⌉,
#   i.e. step λ_j = f0 / ā_j if ā_j > 0, (1 - f0) / (-ā_j) if ā_j < 0, ∞ if
#   ā_j = 0. The cut through those intersection points is
#
#       Σ_j x_j / λ_j >= 1.
#
# * Gomory fractional cut (GFC, Gomory 1958), pure-integer problems only:
#
#       Σ_j frac(ā_j) x_j >= f0.
#
#   It needs every non-basic variable, slacks included, to be integer, so each
#   row is first scaled to integer coefficients and right-hand side (then the
#   slack of an integer point is integer too).
#
# * GMI: the same cut as SIC, with the coefficients of integer non-basic variables
#   strengthened to  min(f_j / f0, (1 - f_j) / (1 - f0)),  f_j = ā_j - ⌊ā_j⌋.
#   Hence GMI coefficients are never larger than SIC ones: GMI dominates SIC.
#
# Slack variables are treated as continuous (always valid) and are finally
# substituted out (s = b - A x) so the cut is stated in the original variables.
# =============================================================================

"""
    tableau_row_data(std_model, var_index; optimizer = HiGHS.Optimizer)

Solve the normal form of the standard-form model `std_model` and return the
data shared by tableau cuts for variable `var_index`, as a named tuple:
`ā` (tableau-row entry of every non-basic variable, by name), `f0` (fractional
part of the row's right-hand side), the optimal-tableau info `opt` and the
standard-form data `data`.
"""
function tableau_row_data(std_model::Model, var_index::Int; optimizer = HiGHS.Optimizer)
    normal_model = create_normal_form_model(std_model)
    optimize_model!(normal_model; optimizer)
    opt = generate_optimal_simplex_tableau(normal_model)

    row = findfirst(==(opt.structural[var_index]), opt.tableau.BasisVars)
    row === nothing && error("Variable $var_index is non-basic, so its value is integral; no tableau cut.")
    b̄ = opt.tableau[row, :rhs]
    f0 = b̄ - floor(b̄)
    1e-6 < f0 < 1 - 1e-6 || error("Variable $var_index is integral in the LP optimum; no tableau cut.")

    ā = Dict(v => opt.tableau[row, v] for v in opt.nonbasic)
    return (ā = ā, f0 = f0, opt = opt, data = lp_matrix_data(std_model))
end

"""
    nonbasic_cut_to_original(coef, opt, data) -> (α, β)

Turn a cut `Σ_j coef[j] x_j >= 1` on the non-basic variables into `α'x >= β`
on the structural variables by substituting the slacks `s = b - A x`.
"""
function nonbasic_cut_to_original(coef::Dict, opt, data)
    A, b = Matrix(data.A), data.b_upper
    n = length(opt.structural)
    π = [get(coef, opt.structural[j], 0.0) for j in 1:n]
    σ = [get(coef, opt.variables[n+i], 0.0) for i in 1:size(A, 1)]
    return π .- A' * σ, 1 - σ' * b
end

# ---- Readable derivations -----------------------------------------------------

"""Number as text: an integer, a small fraction (`-1/4`), or 4 significant digits."""
function number_frac_text(x::Real; max_denominator::Int = 1000)
    abs(x - round(x)) < 1e-9 && return string(Int(round(x)))
    r = rationalize(x; tol = 1e-9)
    return denominator(r) <= max_denominator ? "$(numerator(r))/$(denominator(r))" : string(round(x; sigdigits = 4))
end

"""Display name of a normal-form variable: `β[j]` → the j-th standard-form variable, `s[i]` → `s_i`."""
function tableau_var_name(v::AbstractString, std_model::Model)
    startswith(v, "β[") && return name(all_variables(std_model)[parse(Int, v[4:end-1])])
    startswith(v, "s[") && return "s" * v[3:end-1]
    return v
end

"""`a x + b y − c z` from (coefficient, name) pairs; zero coefficients are skipped, an empty name is a constant."""
function linear_text(terms)
    parts = String[]
    for (c, nm) in terms
        abs(c) < 1e-12 && continue
        term = isempty(nm) ? number_frac_text(abs(c)) :                       # constant
               abs(abs(c) - 1) < 1e-12 ? nm : number_frac_text(abs(c)) * " " * nm
        push!(parts, (isempty(parts) ? (c < 0 ? "−" : "") : (c < 0 ? " − " : " + ")) * term)
    end
    return isempty(parts) ? "0" : join(parts)
end

"""Lines describing the tableau row a cut is read from: the row itself and f0."""
function row_derivation(t, std_model::Model, var_index::Int)
    xk = name(all_variables(std_model)[var_index])
    nonbasic = [v for v in t.opt.variables if haskey(t.ā, v)]
    row = linear_text(vcat([(1.0, xk)], [(t.ā[v], tableau_var_name(v, std_model)) for v in nonbasic]))
    b̄ = t.f0 + floor(t.opt.tableau[findfirst(==(t.opt.structural[var_index]), t.opt.tableau.BasisVars), :rhs])
    return ["Tableau row of $xk: $row = $(number_frac_text(b̄))",
            "f0 = frac($(number_frac_text(b̄))) = $(number_frac_text(t.f0))"], nonbasic
end

"""Line `s_i = b_i − A_i x` for every slack with a non-zero cut coefficient."""
function slack_substitution(coef::Dict, t, std_model::Model)
    A, b = Matrix(t.data.A), t.data.b_upper
    xs = name.(all_variables(std_model))
    n = length(xs)
    subs = String[]
    for i in 1:size(A, 1)
        abs(get(coef, t.opt.variables[n+i], 0.0)) > 1e-12 || continue
        push!(subs, "s$i = " * linear_text(vcat([(b[i], "")], [(-A[i, j], xs[j]) for j in 1:n])))
    end
    return isempty(subs) ? String[] : ["Substituting " * join(subs, ", ") * " gives the inequality above in x."]
end

"""
    intersection_step_lengths(ā, f0) -> Dict{String,Float64}

Step length λ_j along each ray of the LP cone until the split variable hits
`⌊b̄⌋` or `⌈b̄⌉` (`Inf` when the ray is parallel to the split).
"""
function intersection_step_lengths(ā::Dict, f0::Real; atol::Real = 1e-12)
    return Dict(v => a > atol ? f0 / a : a < -atol ? (1 - f0) / (-a) : Inf for (v, a) in ā)
end

"""
    sic_cut(std_model, var_index; optimizer = HiGHS.Optimizer) -> (α, β, λ, derivation)

Standard intersection cut `α'x >= β` from the split on variable `var_index`
and the LP cone at the optimum of the standard-form model `std_model`.
Also returns the step lengths `λ` (by non-basic variable name) and a
human-readable `derivation` (vector of lines).
"""
function sic_cut(std_model::Model, var_index::Int; optimizer = HiGHS.Optimizer)
    t = tableau_row_data(std_model, var_index; optimizer)
    λ = intersection_step_lengths(t.ā, t.f0)
    coef = Dict(v => isfinite(l) ? 1 / l : 0.0 for (v, l) in λ)
    α, β = nonbasic_cut_to_original(coef, t.opt, t.data)

    lines, nonbasic = row_derivation(t, std_model, var_index)
    nm(v) = tableau_var_name(v, std_model)
    push!(lines, "Step to the split boundary along each ray: " *
                 join(["λ($(nm(v))) = $(isfinite(λ[v]) ? number_frac_text(λ[v]) : "∞")" for v in nonbasic], ", "))
    push!(lines, "Cut Σ x_j / λ_j ≥ 1: " * linear_text([(coef[v], nm(v)) for v in nonbasic]) * " ≥ 1")
    append!(lines, slack_substitution(coef, t, std_model))
    return (α = α, β = β, λ = λ, derivation = lines)
end

"""
    integer_scaled_model(std_model; max_denominator = 10_000) -> Model

Copy of a standard-form model with every row `A_i x <= b_i` multiplied by the
smallest positive integer that makes all its coefficients and its right-hand
side integral, so that row slacks are integer at integer points. Throws if a
row needs a multiplier above `max_denominator` (e.g. irrational data).
"""
function integer_scaled_model(std_model::Model; max_denominator::Int = 10_000)
    data = lp_matrix_data(std_model)
    A, b = Matrix(data.A), data.b_upper
    n = size(A, 2)
    isint(v) = all(x -> abs(x - round(x)) <= 1e-9 * max(1, abs(x)), v)

    scaled = Model()
    @variable(scaled, x[1:n] >= 0)
    set_name.(x, name.(data.variables))
    for i in 1:size(A, 1)
        row = vcat(A[i, :], b[i])
        k = findfirst(k -> isint(k .* row), 1:max_denominator)
        k === nothing && error("Row $i cannot be scaled to integer coefficients " *
                               "(needs a multiplier above $max_denominator).")
        set_name(@constraint(scaled, round.(k .* A[i, :])' * x <= round(k * b[i])), name(data.affine_constraints[i]))
    end
    sense = data.sense == MOI.MIN_SENSE ? MIN_SENSE : MAX_SENSE
    @objective(scaled, sense, data.c' * x + data.c_offset)
    return scaled
end

"""
    gomory_fractional_cut(std_model, var_index, integer_vars; optimizer = HiGHS.Optimizer)
        -> (α, β, rescaled, derivation)

Gomory fractional cut `α'x >= β` from the tableau row of variable `var_index`.
Only valid for **pure integer** problems: throws unless every structural
variable is in `integer_vars`. Rows are scaled to integer data first
(`integer_scaled_model`) so the slacks are integer as well; `rescaled` reports
whether any row had to be scaled, `derivation` explains the cut line by line.
"""
function gomory_fractional_cut(std_model::Model, var_index::Int, integer_vars; optimizer = HiGHS.Optimizer)
    n = length(all_variables(std_model))
    length(intersect(integer_vars, 1:n)) == n ||
        error("The Gomory fractional cut needs every variable to be integer; this problem has continuous " *
              "variables. Use the GMI cut instead.")
    scaled = integer_scaled_model(std_model)
    rescaled = Matrix(lp_matrix_data(scaled).A) != Matrix(lp_matrix_data(std_model).A)
    t = tableau_row_data(scaled, var_index; optimizer)
    frac = Dict(v => a - floor(a) for (v, a) in t.ā)               # frac(ā_j)
    coef = Dict(v => f / t.f0 for (v, f) in frac)                   # Σ frac(ā_j)/f0 x_j >= 1
    α, β = nonbasic_cut_to_original(coef, t.opt, t.data)

    lines, nonbasic = row_derivation(t, scaled, var_index)
    rescaled && pushfirst!(lines, "Rows were scaled to integer coefficients first, so every slack is integer.")
    nm(v) = tableau_var_name(v, scaled)
    push!(lines, "Fractional parts of the non-basic coefficients: " *
                 join(["frac($(number_frac_text(t.ā[v]))) = $(number_frac_text(frac[v])) for $(nm(v))" for v in nonbasic], ", "))
    push!(lines, "Cut Σ frac(ā_j) x_j ≥ f0: " * linear_text([(frac[v], nm(v)) for v in nonbasic]) *
                 " ≥ $(number_frac_text(t.f0))")
    append!(lines, slack_substitution(coef, t, scaled))
    return (α = α, β = β, rescaled = rescaled, derivation = lines)
end

"""
    gmi_cut(std_model, var_index, integer_vars; optimizer = HiGHS.Optimizer) -> (α, β, derivation)

GMI cut `α'x >= β` from the tableau row of variable `var_index` in the
LP optimum of the standard-form model `std_model` (`max c'x, Ax <= b, x >= 0`).
`integer_vars` lists the integer structural variables.
"""
function gmi_cut(std_model::Model, var_index::Int, integer_vars; optimizer = HiGHS.Optimizer)
    t = tableau_row_data(std_model, var_index; optimizer)
    f0 = t.f0
    integer_names = Set(t.opt.structural[integer_vars])
    coef = Dict{String,Float64}()
    for (v, a) in t.ā
        if v in integer_names
            f = a - floor(a)
            coef[v] = min(f / f0, (1 - f) / (1 - f0))
        else
            coef[v] = max(a / f0, -a / (1 - f0))       # = 1 / λ_j, the SIC coefficient
        end
    end
    α, β = nonbasic_cut_to_original(coef, t.opt, t.data)

    lines, nonbasic = row_derivation(t, std_model, var_index)
    nm(v) = tableau_var_name(v, std_model)
    push!(lines, "Coefficients: min(f_j/f0, (1−f_j)/(1−f0)) for integer x_j, max(ā_j/f0, −ā_j/(1−f0)) for continuous ones (slacks)")
    push!(lines, "Cut: " * linear_text([(coef[v], nm(v)) for v in nonbasic]) * " ≥ 1")
    append!(lines, slack_substitution(coef, t, std_model))
    return (α = α, β = β, derivation = lines)
end
